<?php
declare(strict_types=1); require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../includes/auth.php'; require_role('student');
$user=current_user(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['invitation_id']??0);$action=post('action');$s=$pdo->prepare('SELECT ce.*,c.title,c.course_code FROM course_enrollments ce JOIN courses c ON c.id=ce.course_id WHERE ce.id=? AND ce.user_id=? AND ce.role="student" AND ce.status="pending" LIMIT 1');$s->execute([$id,$user['id']]);$inv=$s->fetch();if(!$inv){flash('error','Invitation not found or already processed.');redirect('student/invitations.php');}$new=$action==='accept'?'accepted':($action==='decline'?'declined':'');if(!$new){flash('error','Invalid action.');redirect('student/invitations.php');}$pdo->beginTransaction();try{$u=$pdo->prepare('UPDATE course_enrollments SET status=?,responded_at=NOW() WHERE id=?');$u->execute([$new,$id]);if($new==='accepted'){$x=$pdo->prepare('INSERT INTO enrollments(student_id,course_id,status) VALUES(?,? ,"active") ON DUPLICATE KEY UPDATE status="active"');$x->execute([$user['id'],$inv['course_id']]);}$n=$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=? AND type="course_invitation" AND message LIKE ?');$n->execute([$user['id'],'%'.$inv['course_code'].'%']);$pdo->commit();flash('success',$new==='accepted'?'Course accepted and added to My Courses.':'Course invitation declined.');}catch(Throwable $e){$pdo->rollBack();flash('error','Unable to update the invitation.');}redirect('student/invitations.php');}
$s=$pdo->prepare('SELECT ce.id,ce.invited_at,c.title,c.course_code,c.description,s.name section_name,s.school_year,CONCAT(a.first_name," ",a.last_name) invited_by FROM course_enrollments ce JOIN courses c ON c.id=ce.course_id LEFT JOIN sections s ON s.id=c.section_id JOIN users a ON a.id=ce.invited_by WHERE ce.user_id=? AND ce.role="student" AND ce.status="pending" ORDER BY ce.invited_at DESC');$s->execute([$user['id']]);$rows=$s->fetchAll();
$page_title='Course Invitations'; require __DIR__.'/../includes/header.php';
?><div class="app"><aside class="sidebar"><div class="brand"><div class="brand-mark"><i class="fa-solid fa-graduation-cap"></i></div><div><strong>EdubridgeAcademy</strong><span>Student</span></div></div><nav class="nav"><a href="dashboard.php"><i class="fa-solid fa-grid-2"></i>Dashboard</a><a href="courses.php"><i class="fa-solid fa-book-open"></i>My Courses</a><a href="invitations.php" class="active"><i class="fa-solid fa-envelope-open-text"></i>Course Invitations</a><a href="grades.php"><i class="fa-solid fa-chart-line"></i>Grades</a><a href="announcements.php"><i class="fa-solid fa-bullhorn"></i>Announcements</a><a href="../google_account.php"><i class="fa-brands fa-google"></i>Google Account</a>
<div class="nav-sep"></div><a href="../logout.php"><i class="fa-solid fa-right-from-bracket"></i>Sign out</a></nav></aside><main class="main"><header class="topbar"><div><span class="eyebrow">Student portal</span><h1>Course Invitations</h1></div><div class="user-chip"><div class="avatar"><?=e(strtoupper(substr($user['first_name'],0,1).substr($user['last_name'],0,1)))?></div><div><b><?=e($user['first_name'].' '.$user['last_name'])?></b><span>Student</span></div></div></header><div class="content"><div class="section-head"><div><span class="eyebrow">Pending</span><h2>Course Invitations</h2></div></div><?php if(!$rows):?><section class="card empty"><i class="fa-solid fa-envelope-open"></i><p>No pending course invitations.</p></section><?php else:?><div class="grid two"><?php foreach($rows as $r):?><section class="card card-pad"><span class="eyebrow"><?=e($r['course_code'])?></span><h3><?=e($r['title'])?></h3><p class="muted"><?=e($r['description']??'')?></p><small class="muted"><i class="fa-solid fa-layer-group"></i> <?=e($r['section_name']??'Unsectioned')?> · <?=e($r['school_year']??'')?> · Invited by <?=e($r['invited_by'])?> · <?=e(date('M d, Y h:i A',strtotime($r['invited_at'])))?></small><form method="post" class="actions" style="margin-top:16px"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="invitation_id" value="<?=$r['id']?>"><button class="btn btn-primary" name="action" value="accept"><i class="fa-solid fa-check"></i>Accept</button><button class="btn btn-danger" name="action" value="decline"><i class="fa-solid fa-xmark"></i>Decline</button></form></section><?php endforeach;?></div><?php endif;?></div></main></div><?php require __DIR__.'/../includes/footer.php'; ?>
